    req.headers().iter().any(|h| {
        if !h.field.equiv("Authorization") {
            return false;
        }
        let v = h.value.as_bytes();
        v.len() == EXPECTED_PREFIX.len() + token_bytes.len()
            && v.starts_with(EXPECTED_PREFIX)
            && ct_eq_bytes(&v[EXPECTED_PREFIX.len()..], token_bytes)
    })
}

