/// `tags` is normalized and length-bounded at the deserialize boundary so
/// handlers cannot forget per-tag / count limits.
fn deserialize_tags<'de, D>(de: D) -> Result<Option<Vec<String>>, D::Error>
where
    D: serde::Deserializer<'de>,
{
    let raw: Option<Vec<String>> = Option::deserialize(de)?;
    raw.map(|v| {
        if v.len() > API_MAX_TAGS {
            return Err(serde::de::Error::custom(format!("tags 过多（上限 {API_MAX_TAGS}）")));
        }
        v.into_iter()
            .map(|t| {
                if t.chars().count() > API_MAX_TAG_LEN {
                    Err(serde::de::Error::custom(format!("tag 过长（上限 {API_MAX_TAG_LEN} 字）")))
                } else {
                    Ok(t)
                }
            })
            .collect()
    }).transpose()
}

