pub(crate) fn read_log_tail(path: &Path, limit: Option<usize>) -> CommandResult<String> {
    use std::collections::VecDeque;
    use std::io::{BufRead, BufReader};

    let f = match std::fs::File::open(path) {
        Ok(f) => f,
        Err(e) if e.kind() == std::io::ErrorKind::NotFound => {
            return Ok("（暂无日志）".into());
        }
        Err(e) => return Err(CommandError::IoError(format!("读取日志失败：{e}"))),
    };
    let limit = limit.unwrap_or(200).clamp(1, 2000);
    let reader = BufReader::new(f);

    // 保留最近 limit 行：环形缓冲，单次遍历，O(limit) 内存。
    let mut ring: VecDeque<String> = VecDeque::with_capacity(limit);
    for line in reader.lines() {
        let line = line.map_err(|e| CommandError::IoError(format!("读取日志失败：{e}")))?;
        if ring.len() == limit {
            ring.pop_front();
        }
        ring.push_back(line);
    }
    let mut out: Vec<String> = ring.into_iter().rev().collect();
    Ok(out.join("\n"))
}

