pub(crate) fn base_url_is_safe(url: &str) -> bool {
    let u = url.trim();
    if u.is_empty() || u.starts_with("https://") {
        return true;
    }
    let parsed = match url::Url::parse(u) {
        Ok(p) => p,
        Err(_) => return false,
    };
    if parsed.scheme() != "http" {
        return false;
    }
    if !parsed.username().is_empty() || parsed.password().is_some() {
        return false;
    }
    matches!(parsed.host(), Some(url::Host::Domain("localhost")) | Some(url::Host::Ipv4(v4)) if v4.is_loopback())
        || matches!(parsed.host(), Some(url::Host::Ipv6(v6)) if v6.is_loopback())
}

