fn path_openable_in(
    path: &str,
    set: &std::collections::HashSet<String>,
    gen_dir: Option<&std::path::Path>,
) -> bool {
    // 两边统一 canonicalize：避免 raw-string 命中与 canonical 命中的行为分叉
    // （macOS /private/var vs /var、Windows 8.3 短名、./ 与尾斜杠等）。
    let canonical = std::fs::canonicalize(path).ok();
    let canonical_str = canonical.as_ref().and_then(|p| p.to_str());

    if let Some(cs) = canonical_str {
        if set.contains(cs) {
            return true;
        }
    }
    if set.contains(path) {
        // 允许 raw-string 精确命中作为「集合语义是精确路径」的回退路径；
        // 若想严格统一，可改为 set.contains(cs) only。
        return true;
    }
    let Some(gen) = gen_dir.and_then(|d| std::fs::canonicalize(d).ok()) else {
        return false;
    };
    match canonical {
        Ok(c) => c.starts_with(&gen),
        Err(_) => false,
    }
}
```

