pub(crate) enum RollbackOpen {
    Opened,
    NotFound,
    NotFailedOrWrongSession { state: SkillState },
}

pub(crate) fn reopen_failed_run_for_rollback<R: tauri::Runtime>(
    app: &AppHandle<R>,
    name: &str,
    session_id: Option<&str>,
) -> RollbackOpen {
    let registry = skill_runs(app);
    let mut runs = registry.lock().unwrap_or_else(|e| { eprintln!("[mutex_poisoned] bot_skills::state::skill_runs: {e:?}"); e.into_inner() });
    let Some(run) = runs.get_mut(name) else {
        return RollbackOpen::NotFound;
    };
    if run.state == SkillState::Failed && run.session_id.as_deref() == session_id {
        run.state = SkillState::Running;
        return RollbackOpen::Opened;
    }
    RollbackOpen::NotFailedOrWrongSession { state: run.state.clone() }
}

