pub fn reset_bot_assigned_with<F: FnOnce() -> Result<(), String>>(
    done: &std::sync::atomic::AtomicBool,
    exec: F,
) -> bool {
    use std::sync::atomic::Ordering;
    if done.load(Ordering::Acquire) {
        return true;
    }
    match exec() {
        Ok(()) => {
            done.store(true, Ordering::Release);
            true
        }
        Err(_) => false,
    }
}
