pub fn apply_conn_pragmas(conn: &rusqlite::Connection) -> Result<(), String> {
    // journal_mode is special: it returns a row with the mode actually set.
    let mode: String = conn
        .query_row("PRAGMA journal_mode=WAL", [], |r| r.get(0))
        .map_err(|e| e.to_string())?;
    if mode.to_ascii_lowercase() != "wal" {
        return Err(format!("failed to enable WAL journal mode (got {mode:?})"));
    }
    conn.execute_batch(
        "PRAGMA synchronous=NORMAL;
         PRAGMA foreign_keys=ON;",
    )
    .map_err(|e| e.to_string())
}

