/// 返回淘汰数。
pub fn evict_expired(entries: &mut Vec<ProposalEntry>, now_ms: i64) -> usize {
    let before = entries.len();
    entries.retain(|e| {
        !is_expired(e, now_ms)
            || matches!(e.status, ProposalStatus::Promoted | ProposalStatus::Rejected)
    });
    before - entries.len()
}

