/// 计算 expires_at_ms（from_proposal 用）。
/// 当 `created_at_ms` 超出合法窗口（例如来自 jsonl 的损坏/恶意数据）
/// 导致加法溢出时，回落到 saturating_add 并将结果钳为 0（视为立即过期）。
pub fn compute_expires_at(created_at_ms: i64) -> i64 {
    // 合理上限：约公元 2200 年，远大于任何合法 created_at_ms。
    const MAX_REASONABLE_MS: i64 = 7_300_000_000_000_000_000;
    if created_at_ms <= 0 || created_at_ms > MAX_REASONABLE_MS {
        return 0;
    }
    created_at_ms.saturating_add(TTL_MS)
}

