pub fn append(path: &std::path::Path, entry: &ProposalEntry) -> Result<(), String> {
    use std::io::Write;
    if let Some(parent) = path.parent() {
        std::fs::create_dir_all(parent).map_err(|e| format!("建目录 {parent:?} 失败：{e}"))?;
    }
    let mut f = std::fs::OpenOptions::new()
        .create(true)
        .append(true)
        .open(path)
        .map_err(|e| format!("打开 {path:?} 失败：{e}"))?;
    // Serialize concurrent writers on this host so a single line is one atomic write.
    fs2::FileExt::lock_exclusive(&f).map_err(|e| format!("锁定 {path:?} 失败：{e}"))?;
    let line = serde_json::to_string(entry).map_err(|e| format!("序列化失败：{e}"))?;
    writeln!(f, "{line}").map_err(|e| format!("写入 {path:?} 失败：{e}"))?;
    f.sync_all().map_err(|e| format!("sync {path:?} 失败：{e}"))?;
    Ok(())
}

