/// 字符级截断（中文友好）。中文一字 3 字节，按 chars 计数。
/// 截断到 `max` 字符 + 省略号 `…`。单次遍历，O(min(n, max))。
fn truncate_chars(s: &str, max: usize) -> String {
    if s.chars().count() <= max {
        return s.to_string();
    }
    let mut out = String::with_capacity(max * 4 + 3); // 4 bytes/char worst case + ellipsis
    for (i, c) in s.chars().enumerate() {
        if i == max {
            out.push('…');
            break;
        }
        out.push(c);
    }
    out
}

