pub fn transition(from: ChangeStatus, to: ChangeStatus) -> Result<(), String> {
    if from == to {
        return Err(format!("状态未变：{from:?}"));
    }
    if from.is_terminal() {
        return Err(format!("终态不可流转：{from:?} -> {to:?}"));
    }
    if can_transition(from, to) {
        Ok(())
    } else {
        Err(format!("非法 status 流转：{from:?} -> {to:?}"))
    }
}

