        for (name, v) in [
            ("promoted_ratio", self.promoted_ratio),
            ("rejected_ratio", self.rejected_ratio),
            ("expired_ratio", self.expired_ratio),
            ("active_ratio_of_promoted", self.active_ratio_of_promoted),
