        let sum = self.promoted_ratio + self.rejected_ratio + self.expired_ratio;
        if sum > 1.0 {
            return Err(format!("promoted+rejected+expired={sum} > 1.0"));
        }
        if self.window_days < 1 {
            return Err(format!("window_days 须 >= 1，实际 {}", self.window_days));
        }
        Ok(())
    }
}

