pub(crate) fn short_hash(s: &str) -> String {
    // Use a stable, specified hash (SipHash-1-3 with fixed key) instead of
    // `DefaultHasher`, whose algorithm is unspecified and may change between
    // Rust versions, breaking audit dedup stability.
    use siphasher::sip::SipHasher;
    use std::hash::{Hash, Hasher};
    let mut h = SipHasher::new_with_key(&[0; 16]);
    s.hash(&mut h);
    let bytes = h.finish().to_be_bytes();
    let mut out = String::with_capacity(16);
    for b in bytes {
        use std::fmt::Write;
        let _ = write!(out, "{b:02x}");
    }
    out
}

