/// 512 维单热向量（第 i 维为 1）
fn onehot(i: usize) -> Vec<f32> {
    let mut v = vec![0f32; 512];
    v[i % 512] = 1.0;
    v
}

/// 与 onehot(0) 余弦 = w 的向量
fn tilted(w: f32) -> Vec<f32> {
    let mut v = vec![0f32; 512];
    v[0] = w;
    v[1] = (1.0 - w * w).max(0.0).sqrt();
    v
}

