fn unclip_box(b: BoxF, ratio: f32, max_w: f32, max_h: f32) -> BoxF {
        let margin = (ratio - 1.0) / 2.0 * (b.x1 - b.x0).min(b.y1 - b.y0);
        // 对称裁剪：贴边时把被截掉的 margin 从另一边扣回，避免 unclip 不对称
        let left = (b.x0 - margin).max(0.0);
        let top = (b.y0 - margin).max(0.0);
        let consumed_x = b.x0 - left;
        let consumed_y = b.y0 - top;
        let eff_margin_x = (margin - consumed_x).max(0.0);
        let eff_margin_y = (margin - consumed_y).max(0.0);
        BoxF {
            x0: left,
            y0: top,
            x1: (b.x1 + eff_margin_x).min(max_w),
            y1: (b.y1 + eff_margin_y).min(max_h),
        }
    }

