/// Parses an HTTP version string supported by this server (0.9, 1.0, 1.1).
fn parse_http_version(version: &str) -> Result<HTTPVersion, ReadError> {
    let (major, minor) = match version {
        "HTTP/0.9" => (0, 9),
        "HTTP/1.0" => (1, 0),
        "HTTP/1.1" => (1, 1),
        _ => return Err(ReadError::WrongRequestLine),
