let has_close = tokens.split(',').any(|t| t.trim().eq_ignore_ascii_case("close"));
let has_upgrade = tokens.split(',').any(|t| t.trim().eq_ignore_ascii_case("upgrade"));
let has_keep_alive = tokens.split(',').any(|t| t.trim().eq_ignore_ascii_case("keep-alive"));
```

