fn drop(&mut self) {
        let mut remaining_to_read = self.size;
        let mut result: IoResult<()> = Ok(());

        while remaining_to_read > 0 {
            // Use a bounded scratch buffer; allocating `remaining_to_read`
            // bytes up-front is unsafe for arbitrary caller-supplied sizes.
            let mut buf = [0u8; 4096];
            let to_read = remaining_to_read.min(buf.len());

            match self.reader.read(&mut buf[..to_read]) {
                Err(e) => {
                    result = Err(e);
                    break;
                }
                Ok(0) => break, // EOF before limit reached
                Ok(n) => {
                    remaining_to_read -= n;
                }
            }
        }

        // Always signal exactly once on drop so the receiver never deadlocks.
        let _ = self.last_read_signal.send(result);
    }

