export function anchorFromRect(
  x: number,
  y: number,
  w: number,
  sw: number,
): Anchor {
  const MARGIN = 24;
  if (x + w >= sw - MARGIN) return { x: sw - STRIP_W, y, edge: "right" };
  if (x <= MARGIN) return { x: 0, y, edge: "left" };
  if (y <= MARGIN) return { x, y: 0, edge: "top" };
  return { x, y, edge: "float" };
}

