/** crypto.randomUUID 的安全包装——老浏览器/Tauri webview 偶发缺 crypto 时回退
 *  到时间戳拼随机数。仅用于 React key + active 标识，**不可**用于鉴权/去重/共享令牌场景。 */
export function genModelId(): string {
  if (typeof crypto !== "undefined" && typeof crypto.randomUUID === "function") {
    return crypto.randomUUID();
  }
  if (typeof crypto !== "undefined" && typeof crypto.getRandomValues === "function") {
    const bytes = new Uint8Array(8);
    crypto.getRandomValues(bytes);
    const suffix = Array.from(bytes, (b) => b.toString(36).padStart(2, "0")).join("").slice(0, 12);
    return `m-${Date.now().toString(36)}-${suffix}`;
  }
  return `m-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 14)}`;
}

