export const EXEC_TASK_DEDUP_MS = 2000;
const execTaskDedup = new Map<string, number>();

function pruneExecTaskDedup(now: number) {
  for (const [k, t] of execTaskDedup) {
    if (now - t > EXEC_TASK_DEDUP_MS) execTaskDedup.delete(k);
  }
}

export function shouldFireExecTask(key: string, now = Date.now()): boolean {
  pruneExecTaskDedup(now);
  const last = execTaskDedup.get(key);
  if (last !== undefined && now - last <= EXEC_TASK_DEDUP_MS) return false;
  execTaskDedup.set(key, now);
  return true;
}

