function splitAttachments(content: string): { files: string[]; text: string } {
  // Allow optional leading whitespace/BOM and don't require a trailing blank line.
  const m = content.match(/^[\s\uFEFF]*\[附件文件\]\n((?:- .+\n?)+)/);
  if (!m) return { files: [], text: content };
  const raw = m[1];
  const files = raw
    .split("\n")
    .filter((l) => l.startsWith("- "))
    .map((l) => l.slice(2).trim());
  // Consume the matched block plus the single separator newline that precedes the body.
  const consumedLen = m[0].length - (raw.endsWith("\n") ? 1 : 0);
  return { files, text: content.slice(consumedLen).replace(/^\n/, "") };
}

